 const fail=()=>{throw Error('Gmail: invalid canonical encoding, Unicode or 256 KiB byte bound');};let bytes;
 if(mode==='base64-to-raw'){if(typeof inputs.value!=='string'||inputs.value.length>349528||!/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(inputs.value))fail();bytes=Buffer.from(inputs.value,'base64');if(bytes.toString('base64')!==inputs.value)fail();}
 else if(mode==='text-to-raw'){if(typeof inputs.value!=='string'||inputs.value.length>262144)fail();bytes=Buffer.from(inputs.value,'utf8');if(new TextDecoder('utf-8',{fatal:true,ignoreBOM:true}).decode(bytes)!==inputs.value)fail();}
 else{if(typeof inputs.value!=='string'||inputs.value.length>349528||!/^[A-Za-z0-9_-]*={0,2}$/.test(inputs.value))fail();bytes=Buffer.from(inputs.value,'base64url');if(bytes.toString('base64url')!==inputs.value.replace(/=+$/,'')||inputs.value.includes('=')&&inputs.value!==bytes.toString('base64').replaceAll('+','-').replaceAll('/','_'))fail();}
 if(bytes.length>262144)fail();let value;if(mode==='raw-to-text'){try{value=new TextDecoder('utf-8',{fatal:true,ignoreBOM:true}).decode(bytes);}catch{fail();}}else value=bytes.toString(mode==='raw-to-base64'?'base64':'base64url');return {value,byteLength:bytes.length};
})(inputs,"base64-to-raw");

